<script setup lang="ts">
import { ref } from 'vue'
import { app, setTier, setVoice, gs, setSettings, setDice } from '../session'
import { volume, setVolume } from '../audio'
import Modal from './Modal.vue'
import LlmForm from './LlmForm.vue'
const DICE = [['press', 'I press, the game throws', 'Every attack, save and check waits for you.'], ['type', 'I throw real dice', 'The game asks, you type what fell.'], ['auto', 'Throw for me', 'Nothing waits.']] as const; const tab = ref('play'), vol = ref(volume()); const save = () => { localStorage.setItem('rw.dice3d', app.prefs.dice3d ? '1' : '0'); localStorage.setItem('rw.ui', String(app.prefs.scale)) }
</script>
<template><Modal title="Settings" icon="cog" :width="600"><div class="tabs" style="margin:-6px 0 14px"><button v-for="t in [['play', 'Play'], ['dm', 'Dungeon Master'], ['look', 'Picture and sound'], ['about', 'About']]" :key="t[0]" class="tab" :class="{ on: tab === t[0] }" @click="tab = t[0]">{{ t[1] }}</button></div>
  <template v-if="tab === 'play'"><span class="cap">Your dice</span><div class="dm"><button v-for="d in DICE" :key="d[0]" :class="{ on: app.prefs.dice === d[0] }" @click="setDice(d[0])"><b>{{ d[1] }}</b><small>{{ d[2] }}</small></button></div><span class="cap">At the table</span><button class="opt" :class="{ on: app.prefs.dice3d }" @click="app.prefs.dice3d = !app.prefs.dice3d; save()"><i class="tick" /><span>Show other throws rolling across the screen</span></button><button class="opt" :class="{ on: app.prefs.shake }" @click="app.prefs.shake = !app.prefs.shake"><i class="tick" /><span>Shake the view on heavy blows</span></button><button class="opt" :class="{ on: app.voice }" @click="setVoice(!app.voice)"><i class="tick" /><span>Read the story aloud, in your device’s own voices</span></button><label class="lab">Size of the interface: {{ Math.round(app.prefs.scale * 100) }}%</label><input v-model.number="app.prefs.scale" type="range" min=".8" max="1.4" step=".05" aria-label="Interface size" @change="save"></template>
  <template v-if="tab === 'dm'"><p class="muted">Used when the AI runs the game. The built-in Storyteller is always there and takes over if a model fails.</p><LlmForm /><template v-if="gs && app.hosting"><span class="cap">This campaign</span><button class="opt" :class="{ on: gs.set.askDice }" @click="setSettings({ askDice: !gs.set.askDice })"><i class="tick" /><span>Players throw their own dice</span></button><button class="opt" :class="{ on: gs.set.handDice }" @click="setSettings({ handDice: !gs.set.handDice })"><i class="tick" /><span>Players may throw real dice and type the result</span></button><button class="opt" :class="{ on: gs.set.ownSheets }" @click="setSettings({ ownSheets: !gs.set.ownSheets })"><i class="tick" /><span>Players may amend their own sheets</span></button><button v-if="gs.camp?.mod && app.role === 'dm' && gs.mode !== 'ai'" class="opt" :class="{ on: gs.set.autoScenes }" @click="setSettings({ autoScenes: !gs.set.autoScenes })"><i class="tick" /><span>Scenes of the campaign begin by themselves when the heroes arrive</span></button><button class="opt" :class="{ on: gs.set.wander }" @click="setSettings({ wander: !gs.set.wander })"><i class="tick" /><span>Wandering creatures</span></button><button class="opt" :class="{ on: gs.set.endless }" @click="setSettings({ endless: !gs.set.endless })"><i class="tick" /><span>The map grows at its edge</span></button><label class="lab">Experience × {{ gs.set.xpRate }}</label><input :value="gs.set.xpRate" type="range" min=".25" max="4" step=".25" aria-label="XP rate" @change="setSettings({ xpRate: +($event.target as HTMLInputElement).value })"><label class="lab">{{ gs.set.rollSecs ? `Throw for a slow player after ${gs.set.rollSecs} seconds` : 'Wait for slow players' }}</label><input :value="gs.set.rollSecs" type="range" min="0" max="180" step="15" aria-label="Roll timer" @change="setSettings({ rollSecs: +($event.target as HTMLInputElement).value })"><label class="lab">{{ gs.set.turnSecs ? `${gs.set.turnSecs} seconds a turn` : 'No turn timer' }}</label><input :value="gs.set.turnSecs" type="range" min="0" max="180" step="15" aria-label="Turn timer" @change="setSettings({ turnSecs: +($event.target as HTMLInputElement).value })"></template></template>
  <template v-if="tab === 'look'"><label class="lab">Volume</label><input v-model.number="vol" type="range" min="0" max="1" step=".02" aria-label="Volume" @input="setVolume(vol)"><span class="lab">Picture quality</span><div class="chips"><button v-for="t in (['low', 'medium', 'high', 'ultra'] as const)" :key="t" class="chip" :class="{ on: app.tier === t }" @click="setTier(t)">{{ t[0].toUpperCase() + t.slice(1) }}</button></div><p class="muted" style="margin-top:8px">{{ app.stats.fps ?? '–' }} frames a second. {{ app.software ? 'This browser is drawing without a graphics card.' : app.gpu }}</p></template>
  <template v-if="tab === 'about'"><p>This work includes material taken from the System Reference Document 5.1 (“SRD 5.1”) by Wizards of the Coast LLC and available at <a class="link" href="https://dnd.wizards.com/resources/systems-reference-document" target="_blank" rel="noopener">dnd.wizards.com</a>. The SRD 5.1 is licensed under the Creative Commons Attribution 4.0 International License.</p><p class="muted">Realmwright is not affiliated with Wizards of the Coast. The Eye Tyrant is our own creature. Icons by the game-icons.net authors, CC BY 3.0. Typefaces Jost and Grenze, SIL OFL. PDF sheets are read with pdf.js, Apache 2.0. The campaigns, models and textures were made for this game.</p></template></Modal></template>
<style scoped>.dm{display:grid;grid-template-columns:repeat(3,1fr);border:2px solid var(--ink)}.dm button{padding:9px 12px 11px;border-right:2px solid var(--ink)}.dm button:last-child{border:0}.dm b{display:block;font:700 20px/1.05 var(--serif)}.dm small{font-size:15px;line-height:1.2;display:block;margin-top:3px;color:var(--ink2)}.dm .on{background:var(--ink);color:var(--paper)}.dm .on small{color:#c9ced4}@media(max-width:600px){.dm{grid-template-columns:1fr}.dm button{border-right:0;border-bottom:2px solid var(--ink)}}</style>
